    # Strategy 5: Coprime and primitive element search
    # Codes perform better when exponents are coprime to ell or m.
    import math
    def get_coprimes(n):
        return [i for i in range(1, n) if math.gcd(i, n) == 1]

    cx = get_coprimes(ell)[:4]
    cy = get_coprimes(m)[:4]

